sparql:
SELECT DISTINCT ?item ?field0 ?field1 WHERE {
  ?item a <urn:t04:Alarm> .
  ?item <urn:t04:severity> ?condition0 .
  FILTER (?condition0 = "High")
  ?item <urn:t04:status> ?condition1 .
  FILTER (?condition1 = "Open")
  OPTIONAL { ?item <urn:t04:severity> ?field0 . }
  OPTIONAL { ?item <urn:t04:status> ?field1 . }
}
ORDER BY ?item ?field0 ?field1
